const TOKEN = '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';
console.log(`Token length: ${TOKEN.length}`);
console.log(`Token prefix: ${TOKEN.slice(0, 8)}`);

// Test 1: /user endpoint
const res1 = await fetch('https://api.github.com/user', {
  headers: { 
    Authorization: `Bearer ${TOKEN}`,
    Accept: 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
    'User-Agent': 'ivx-deploy-agent',
  },
});
console.log(`\nTest 1 (Bearer): HTTP ${res1.status}`);
const data1 = await res1.json();
console.log(`Response: ${JSON.stringify(data1).slice(0, 200)}`);

// Test 2: token endpoint
const res2 = await fetch('https://api.github.com/user', {
  headers: { 
    Authorization: `token ${TOKEN}`,
    'User-Agent': 'ivx-deploy-agent',
  },
});
console.log(`\nTest 2 (token): HTTP ${res2.status}`);
const data2 = await res2.json();
console.log(`Response: ${JSON.stringify(data2).slice(0, 200)}`);
SCRIPT
