input.command:
cat > /tmp/final_token_test.mjs << 'SCRIPT'
// Exact token as provided by user
const TOKEN = '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';
const clean = TOKEN.trim();

console.log(`Raw length: ${TOKEN.length}`);
console.log(`Trimmed length: ${clean.length}`);
console.log(`Chars: ${[...clean].map(c => c.charCodeAt(0)).join(',')}`);
console.log(`Prefix: ${clean.slice(0, 4)}`);

// Try all auth methods
const tests = [
  { name: 'Bearer', headers: { Authorization: `Bearer ${clean}` } },
  { name: 'token', headers: { Authorization: `token ${clean}` } },
  { name: 'Basic', headers: { Authorization: `Basic ${Buffer.from(clean + ':').toString('base64')}` } },
];

for (const t of tests) {
  const res = await fetch('https://api.github.com/user', {
    headers: { ...t.headers, 'User-Agent': 'ivx-deploy', Accept: 'application/vnd.github+json' },
  });
  const body = await res.json();
  console.log(`${t.name}: HTTP ${res.status} — ${body.login || body.message}`);
}
SCRIPT
bun /tmp/final_token_test.mjs

